import raw from './recipes.json';
import type {MatchSummary, PantryItem, Recipe} from '$lib/types';
import {same} from '$lib/match';
import {evaluate} from '$lib/evaluate';
import {summarize} from '$lib/score';
import {EXCLUDE_TERMS} from '$lib/constants';

// The recipe catalog lives only on the server (generated by scripts/build-recipes.mjs).
const catalog = raw as unknown as Recipe[];
const byId = new Map(catalog.map((r) => [r.id, r]));
export const getRecipe = (id: string) => byId.get(id);
export const catalogSize = catalog.length;

// key -> recipes that REQUIRE that ingredient. A recipe can only appear if one of these keys matches the pantry.
const index = new Map<string, number[]>();
catalog.forEach((r, i) => {
  for (const k of new Set(r.ingredients.filter((x) => !x.optional && !x.staple).map((x) => x.key))) {
    const list = index.get(k);
    if (list) list.push(i); else index.set(k, [i]);
  }
});
const keys = [...index.keys()];
const memo = new Map<string, string[]>();
function keysFor(name: string): string[] {
  let m = memo.get(name);
  if (!m) { m = keys.filter((k) => same(name, k)); if (memo.size > 500) memo.clear(); memo.set(name, m); }
  return m;
}
const hit = (text: string, t: string) => text.includes(t) && !(text.includes('coconut') && (t === 'milk' || t === 'cream'));

/** Recipes with at least one matching required ingredient, best first. Recipes with no match are never returned. */
export function rank(pantry: PantryItem[], exclusions: string[]): MatchSummary[] {
  const keyMap = new Map<string, PantryItem>();
  for (const p of pantry) for (const k of keysFor(p.name)) if (!keyMap.has(k)) keyMap.set(k, p);
  const candidates = new Set<number>();
  for (const k of keyMap.keys()) for (const i of index.get(k)!) candidates.add(i);
  const terms = exclusions.flatMap((x) => EXCLUDE_TERMS[x] ?? [x.toLowerCase()]);
  const out: MatchSummary[] = [];
  for (const i of candidates) {
    const r = catalog[i];
    if (terms.length && r.ingredients.some((g) => terms.some((t) => hit(g.raw.toLowerCase(), t)))) continue;
    const e = evaluate(r, (g) => keyMap.get(g.key));
    if (e.matched > 0) out.push(summarize(e));
  }
  return out.sort((a, b) => b.pct - a.pct || b.have - a.have || a.missing.length - b.missing.length || a.name.localeCompare(b.name));
}
